-- =====================================================================
-- IMPORT: FIXIT-KUNDER -> nye systemet (Vani + Soren)  [v6 - alt-i-ett, vanntett]
--   Kjor BARE denne fila. Lager kobling-tabellen selv. Idempotent. En transaksjon.
--   * Samtykke settes fra EKTE AcceptedEmail per kunde.
--   * Vern mot unik e-post (uq_customers_email_ci) og mot dublett-koblinger.
-- =====================================================================
begin;

alter table customers add column if not exists import_key text;
create unique index if not exists customers_import_key_uidx on customers(import_key) where import_key is not null;

create table if not exists customer_barbers (
  customer_id uuid not null references customers(id) on delete cascade,
  staff_id    uuid not null references staff(id)     on delete cascade,
  visits integer, last_visit date, total_spent numeric(12,2),
  source text default 'fixit', created_at timestamptz not null default now(),
  primary key (customer_id, staff_id)
);
create index if not exists customer_barbers_staff_idx on customer_barbers (staff_id);
alter table customer_barbers enable row level security;
drop policy if exists customer_barbers_admin_all on customer_barbers;
create policy customer_barbers_admin_all on customer_barbers for all using (is_admin()) with check (is_admin());
drop policy if exists customer_barbers_shop_read on customer_barbers;
create policy customer_barbers_shop_read on customer_barbers for select using (is_shop_or_admin());

create temp table fixit_cust (import_key text primary key, full_name text, phone text, email text, first_visit date, consent boolean) on commit drop;
create temp table fixit_link (import_key text, barber_name text, visits int, last_visit date, total_spent numeric) on commit drop;

