-- Koble eksisterende kunder til import-nokkel (maks en kunde per nokkel, en nokkel per kunde).
with matches as (
  select c.id as cid, s.import_key,
         row_number() over (partition by s.import_key order by c.created_at, c.id) as rn
  from customers c join fixit_cust s
    on c.import_key is null
   and ( (c.phone is not null and c.phone = s.phone)
      or (c.email is not null and s.email is not null and lower(c.email)=lower(s.email)) )
),
pick as (select distinct on (cid) cid, import_key from matches where rn=1 order by cid, import_key)
update customers c set import_key = pick.import_key from pick where c.id = pick.cid;

-- 1) Oppdater matchede kunder (behold eksisterende e-post; fyll bare hvis tom OG ledig).
update customers c set
  full_name = coalesce(nullif(s.full_name,''), c.full_name),
  phone     = coalesce(s.phone, c.phone),
  email = case
            when c.email is not null and trim(c.email) <> '' then c.email
            when s.email is not null and not exists (select 1 from customers c2 where c2.id<>c.id and lower(trim(c2.email))=lower(trim(s.email))) then s.email
            else c.email end,
  first_visit = least(coalesce(c.first_visit, s.first_visit), coalesce(s.first_visit, c.first_visit)),
  marketing_consent    = (coalesce(c.marketing_consent,false) or s.consent),
  marketing_consent_at = case when (coalesce(c.marketing_consent,false) or s.consent) then coalesce(c.marketing_consent_at, now()) else null end
from fixit_cust s where c.import_key = s.import_key;

-- 2) Sett inn nye kunder (e-post bare hvis ledig, ellers NULL -> aldri unik-brudd).
insert into customers (import_key, full_name, phone, email, first_visit, marketing_consent, marketing_consent_at)
select s.import_key, s.full_name, s.phone,
       case when s.email is null or trim(s.email)='' then null
            when exists (select 1 from customers c where lower(trim(c.email))=lower(trim(s.email))) then null
            when row_number() over (partition by lower(trim(s.email)) order by s.import_key) > 1 then null
            else s.email end,
       s.first_visit, s.consent, case when s.consent then now() else null end
from fixit_cust s
where not exists (select 1 from customers c where c.import_key = s.import_key);

-- 3) Aggreger koblinger -> EN rad per (kunde, barber). Dette fjerner dublett-pkey helt.
create temp table fixit_linkagg on commit drop as
select c.id as customer_id, st.id as staff_id,
       max(l.visits) as visits, max(l.last_visit) as last_visit, max(l.total_spent) as total_spent
from fixit_link l
join customers c on c.import_key = l.import_key
join staff st on lower(st.full_name) = lower(l.barber_name)
group by c.id, st.id;

insert into customer_barbers (customer_id, staff_id, visits, last_visit, total_spent, source)
select la.customer_id, la.staff_id, la.visits, la.last_visit, la.total_spent, 'fixit'
from fixit_linkagg la
where not exists (select 1 from customer_barbers cb where cb.customer_id=la.customer_id and cb.staff_id=la.staff_id);

update customer_barbers cb set visits=la.visits, last_visit=la.last_visit, total_spent=la.total_spent, source='fixit'
from fixit_linkagg la where cb.customer_id=la.customer_id and cb.staff_id=la.staff_id;

do $$
declare missing text;
begin
  select string_agg(distinct l.barber_name, ', ') into missing from fixit_link l
  where not exists (select 1 from staff st where lower(st.full_name)=lower(l.barber_name));
  if missing is not null then
    raise notice 'ADVARSEL: fant ikke disse barberne i staff (lenker hoppet over): %. Opprett dem og kjor importen pa nytt.', missing;
  end if;
end $$;
commit;
